export function getProvider(name: string): FeedProvider {
  const normalized = PROVIDER_ALIASES[name] ?? name;
  const p = PROVIDERS[normalized];
  const valid = [...PROVIDER_NAMES, ...Object.keys(PROVIDER_ALIASES)].sort();
  if (!p) throw new Error(`Unknown provider: ${name}. Valid: ${valid.join(', ')}`);
  return p;
}

/**
 * Resolve the extractor whose provider notes this URL's hostname.
 * The provider registry is the single source of truth for domain → extractor.
 */
export function getExtractor(url: string): FeedProvider['extractor'] {
  let hostname: string;
  try { hostname = new URL(url).hostname.replace(/^www\./, ''); }
  catch { throw new Error(`Invalid URL: ${url}`); }

  for (const p of Object.values(PROVIDERS)) {
    const ext = p.extractor;
    if (ext.domains.some(d => hostname === d || hostname.endsWith(`.${d}`))) return ext;
  }

  const supported = Object.values(PROVIDERS).flatMap(p => p.extractor.domains);
  throw new Error(
    `No extractor registered for "${hostname}". Supported domains: ${supported.join(', ')}`,
  );
}

